from pathlib import Path
import collections, datetime, hashlib, json, os, re, subprocess, time
root=Path('/Users/wkoch/Projetos/xrai');here=root/'docs/relatorios/logs/L5-continuacao/ci-fourth';out=root/'docs/relatorios/logs/revisao-v1';out.mkdir(parents=True,exist_ok=True)
code='c48b5993550fd258f1efe5677704a59d9eb73de0'
def sha(b):return hashlib.sha256(b).hexdigest()
manifest=json.loads((here/'retained-files-manifest.json').read_text());run=json.loads((here/'run.json').read_text());native=json.loads((here/'native-verification.json').read_text())
assert run['headSha']==code and run['conclusion']=='success' and len(run['jobs'])==5 and all(j['conclusion']=='success' for j in run['jobs'])
for p,r in manifest['retained_files'].items():
 b=(here/p).read_bytes();assert len(b)==r['bytes'] and sha(b)==r['sha256'],p
for p,h in manifest['publication_sources_sha256'].items():assert sha((root/p).read_bytes())==h,p
assert native['verified'] and native['code_commit']==code
summaries={}
for target,r in native['targets'].items():
 b=r['binaries'];assert b['verified'] and b['code_commit']==code and len(b['executables'])==6
 m=json.loads((here/f'native-{target}/binaries/manifest.json').read_text());assert b['executables']==m['executables']
 assert r['semantics']['rust-r3']['correct']==34 and r['semantics']['rust-r3']['resolvable_correct']==16
 assert r['semantics']['counterproofs-cfg']['correct']==8
 summaries[target]={'semantics':r['semantics'],'contexts':list(r['contexts']),'recorded_binary_hashes':len(b['executables']),'environment':r['environment']}
commands=[['python3','docs/relatorios/logs/L5-continuacao/reconcile_corpus.py',str(here),'--commit',code,'--run','38283109016'],['python3','eval/scripts/collect_real_rust.py','verify'],['python3','eval/scripts/prepare_l5_js.py','verify']]
receipts=[]
for cmd in commands:
 start=time.monotonic();p=subprocess.run(cmd,cwd=root,env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'},text=True,capture_output=True)
 receipts.append({'command':cmd,'exit_code':p.returncode,'elapsed_seconds':time.monotonic()-start,'stdout':p.stdout,'stderr':p.stderr,'stdout_sha256':sha(p.stdout.encode())});assert p.returncode==0,p.stderr
corpus=json.loads(receipts[0]['stdout']);assert corpus['verified'] and all(v['complete_file_set_verified'] for v in corpus['export_provenance'].values())
rows=re.findall(r'^\| (M[01]-\d+(?:\.R\d+)?) \|[^\n]*?\| ([^|]+?) \|',(root/'docs/STATUS-IMPLEMENTACAO.md').read_text(),re.M)
counts={k:dict(collections.Counter(s for i,s in rows if i.startswith(k))) for k in ['M0','M1']}
assert len(rows)==41 and counts['M0']=={'concluída':9,'em andamento':7,'não iniciada':2} and counts['M1']=={'não iniciada':23}
record={'schema':'xrai.architecture.v1-progress.audit.v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'base_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'code_commit':code,'result':'passed','run':38283109016,'retained_files_verified':len(manifest['retained_files']),'publication_sources_verified':len(manifest['publication_sources_sha256']),'native_receipt_summaries':summaries,'commands':receipts,'cards':{'total':41,'by_phase':counts},'graph_coverage':json.loads(Path('/tmp/xrai-v1-coverage.json').read_text()),'verifier_source':Path(__file__).read_text(),'limits':['Data-only reconciliation; no build, upstream test or paid session executed.','Native binaries/ZIPs absent from current checkout/scratch; only their prior verified receipts and committed manifests reconciled now.','Two committed corpus ZIPs and their complete exported file sets were independently reverified now.','No new GitHub metadata query; provenance relies on retained export.','No competitive admission/gates inferred; no release progress percentage.']}
(out/'evidencias.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:record[k] for k in ['result','retained_files_verified','publication_sources_verified','cards']},ensure_ascii=False,indent=2))
